// eqats/src/valuation/nse_report.rs\nuse pyo3::prelude::*;\n\n#[pyfunction]\nfn research_py(ticker: &str) -> PyResult<PyObject> {\n    Python::with_gil(|py| {\n        let module = py.import_bound(\"equity_research\")?;\n        let func = module.get_bound(\"research_json\")?;\n        let result = func.call1((ticker,))?;\n        Ok(result.into())\n    })\n}\n\n#[pymodule]\nfn eqats_nse(_py: Python, m: &PyModule) -> PyResult<()> {\n    m.add_function(wrap_pyfunction!(research_py, m)?)?;\n    Ok(())\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    #[test]\n    fn test_import() {\n        Python::with_gil(|py| {\n            let m = pyo3::wrap_pyfunction!(research_py, py)?;\n            assert!(m.is_ok());\n        }).unwrap();\n    }\n}